class FrequencyTracker { unordered_map<int,int> numberCount,frequencyCount;void change(int number,int next){int old=numberCount[number];if(old&&!--frequencyCount[old])frequencyCount.erase(old);if(next){numberCount[number]=next;++frequencyCount[next];}else numberCount.erase(number);}public:FrequencyTracker(){}void add(int number){change(number,numberCount[number]+1);}void deleteOne(int number){int old=numberCount[number];if(old)change(number,old-1);}bool hasFrequency(int frequency){return frequencyCount[frequency]>0;} };
